insert into public.startups (slug, cohort_year, display_number, name, category, accent, tags, description, tagline, segment, headline, paragraphs, features, socials, logo_url, team_image_url, sort_order)
values ('selectio', '2026', '02', 'Selectio', 'Tecnologia', 'selectio', '{"pt":["Recrutamento","Indicações","Plataforma"],"en":["Recruitment","Referrals","Platform"]}'::jsonb, '{"pt":"Plataforma web de recrutamento por indicação que organiza vagas, candidatos, processos seletivos e recompensas.","en":"A referral recruitment web platform that organizes job openings, candidates, hiring processes and rewards."}'::jsonb, '{"pt":"Recrutamento por indicação · vagas, talentos e recompensas","en":"Referral recruitment · jobs, talent and rewards"}'::jsonb, '{"pt":"recrutamento por indicação","en":"referral recruitment"}'::jsonb, '{"pt":{"text":"Indicações que","emphasis":"conectam talentos."},"en":{"text":"Referrals that","emphasis":"connect talent."}}'::jsonb, '{"pt":["A Selectio é uma plataforma web para operações de recrutamento baseadas em indicação. A solução reúne a publicação de vagas, o cadastro de candidatos e o acompanhamento de processos seletivos, com áreas específicas para empresas e indicadores. Empresas gerenciam oportunidades, candidatos e entrevistas, enquanto indicadores cadastram talentos e acompanham suas indicações.","O processo inclui o acompanhamento de cada candidato, da indicação à contratação, e o agendamento de entrevistas com histórico e notificações. O ranking de compatibilidade por vaga utiliza critérios ponderados, evidências e revisão humana. A plataforma também organiza as recompensas por indicação, com integração ao Mercado Pago e registro de transações."],"en":["Selectio is a web platform for referral-based recruitment operations. The solution brings together job posting, candidate registration and hiring process tracking, with dedicated areas for companies and referrers. Companies manage opportunities, candidates and interviews, while referrers register talent and track their referrals.","The process includes tracking each candidate from referral to hiring, and scheduling interviews with history and notifications. Compatibility rankings for each job use weighted criteria, evidence and human review. The platform also organizes referral rewards, with Mercado Pago integration and transaction records."]}'::jsonb, '{"pt":[{"title":"Recrutamento por indicação","description":"Vagas, cadastro de talentos e acompanhamento das etapas do processo seletivo em uma única plataforma."},{"title":"Compatibilidade com critérios","description":"Ranking por vaga com critérios ponderados, evidências, alertas e revisão humana."},{"title":"Gestão de recompensas","description":"Pagamentos integrados ao Mercado Pago, registro de transações e acompanhamento financeiro das indicações."}],"en":[{"title":"Referral recruitment","description":"Job openings, talent registration and hiring stage tracking in a single platform."},{"title":"Criteria-based matching","description":"Rankings for each job with weighted criteria, evidence, alerts and human review."},{"title":"Reward management","description":"Payments integrated with Mercado Pago, transaction records and financial tracking of referrals."}]}'::jsonb, '{"instagram":"https://www.instagram.com/selectio_/","linkedin":"https://www.linkedin.com/company/selectioltda/posts/?feedView=all","website":"https://selectio.app.br/"}'::jsonb, 'selectio/logo.png', 'selectio/team.png', 2)
