insert into public.startups (slug, cohort_year, display_number, name, category, accent, tags, description, tagline, segment, headline, paragraphs, features, socials, logo_url, team_image_url, sort_order)
values ('condomit', '2026', '05', 'Condomit', 'Tecnologia', 'condomit', '{"pt":["Condomínios","Gestão","Comunicação"],"en":["Condominiums","Management","Communication"]}'::jsonb, '{"pt":"Plataforma digital que reúne comunicação, serviços e decisões para simplificar a gestão de condomínios.","en":"A digital platform bringing communication, services and decisions together to simplify condominium management."}'::jsonb, '{"pt":"O app do seu condomínio","en":"Your condominium app"}'::jsonb, '{"pt":"gestão condominial","en":"condominium management"}'::jsonb, '{"pt":{"text":"Seu condomínio","emphasis":"em um só lugar."},"en":{"text":"Your condominium","emphasis":"in one place."}}'::jsonb, '{"pt":["A Condomit centraliza a comunicação, a gestão e os serviços do condomínio em um ambiente digital para síndicos, administradores e moradores. Comunicados, eventos, reservas, visitantes e manutenções ficam organizados na mesma plataforma.","Votações, reuniões e assembleias também fazem parte da proposta, facilitando a participação e a tomada de decisões. Ao reunir essas rotinas, a Condomit busca reduzir a dependência de grupos de mensagens, planilhas e processos manuais."],"en":["Condomit brings condominium communication, management and services into one digital space for residents, managers and administrators. Announcements, events, bookings, visitors and maintenance are organized in the same platform.","Voting, meetings and assemblies are also part of the proposal, making participation and decisions easier. By bringing these routines together, Condomit aims to reduce reliance on messaging groups, spreadsheets and manual processes."]}'::jsonb, '{"pt":[{"title":"Rotina integrada","description":"Comunicados, eventos, reservas, visitantes e manutenção em um único ambiente."},{"title":"Decisões participativas","description":"Votações, reuniões e assembleias conectadas à gestão do condomínio."},{"title":"Gestão mais clara","description":"Informações e processos organizados para moradores, síndicos e administradores."}],"en":[{"title":"Connected routines","description":"Announcements, events, bookings, visitors and maintenance in one place."},{"title":"Shared decisions","description":"Voting, meetings and assemblies connected to condominium management."},{"title":"Clearer management","description":"Organized information and processes for residents, managers and administrators."}]}'::jsonb, '{"instagram":"https://www.instagram.com/condomit.ofc/","website":"https://condomit.netlify.app/"}'::jsonb, 'condomit/logo.png', null, 5)
