values ('recure', '2026', '06', 'RECURE', 'Tecnologia', 'recure', '{"pt":["Fisioterapia","Tratamento","Evolução"],"en":["Physiotherapy","Treatment","Progress"]}'::jsonb, '{"pt":"Plataforma digital de fisioterapia que conecta profissionais e pacientes durante a recuperação.","en":"A digital physiotherapy platform connecting professionals and patients throughout recovery."}'::jsonb, '{"pt":"Fisioterapia · acompanhamento · evolução","en":"Physiotherapy · follow-up · progress"}'::jsonb, '{"pt":"fisioterapia digital","en":"digital physiotherapy"}'::jsonb, '{"pt":{"text":"Recuperação com","emphasis":"acompanhamento."},"en":{"text":"Recovery with","emphasis":"guidance."}}'::jsonb, '{"pt":["A RECURE é uma plataforma digital para fisioterapia que conecta profissionais e pacientes. Ela facilita o acompanhamento dos tratamentos e a realização dos exercícios ao longo da recuperação.","A solução também ajuda a monitorar a evolução de cada paciente, com a proposta de tornar o processo de recuperação mais eficiente, prático e motivador."],"en":["RECURE is a digital physiotherapy platform connecting professionals and patients. It helps them follow treatment plans and complete exercises throughout recovery.","The solution also helps monitor each patient’s progress, aiming to make recovery more efficient, practical and motivating."]}'::jsonb, '{"pt":[{"title":"Conexão profissional-paciente","description":"Um espaço digital para acompanhar o tratamento de fisioterapia."},{"title":"Exercícios acompanhados","description":"Apoio para realizar os exercícios durante a recuperação."},{"title":"Evolução monitorada","description":"Visibilidade do progresso para pacientes e profissionais."}],"en":[{"title":"Professional-patient connection","description":"A digital space to follow physiotherapy treatment."},{"title":"Guided exercises","description":"Support for completing exercises during recovery."},{"title":"Progress tracking","description":"Visibility into recovery progress for patients and professionals."}]}'::jsonb, '{"instagram":"https://www.instagram.com/recure.fisio/","linkedin":"https://www.linkedin.com/company/recurephysio/about/","website":"https://recurephysio.com/"}'::jsonb, 'recure/logo.png', 'recure/team.jpg', 6)
